"""Randomized differential test: submission vs. naive reference."""
import json
import random
import sys

sys.path.insert(0, '/workspace/submission')
sys.path.insert(0, '/workspace/tests')

from utils import run_request as fast
from reference import Ref


def borders(rng, U):
    n = rng.randint(1, 4)
    pts = sorted(rng.sample(range(1, U), min(n, U - 1))) if U > 1 else []
    return [0] + pts + [U]


def make_policy(rng):
    kind = rng.choice(['fifo', 'sp', 'sff', 'wfq'])
    flows = rng.sample(range(0, 8), rng.randint(1, 4))
    if kind == 'fifo':
        return {'kind': 'fifo'}, flows
    if kind == 'sff':
        return {'kind': 'sff'}, flows
    if kind == 'sp':
        return {'kind': 'sp', 'levels': [[f, rng.randint(0, 12)] for f in flows]}, flows
    return {'kind': 'wfq', 'weights': [[f, rng.randint(1, 8)] for f in flows]}, flows


def make_run(rng):
    M = rng.randint(1, 4)
    L = rng.randint(1, 3)
    U = rng.randint(1, 24)
    policy, flows = make_policy(rng)
    events = []
    ids = rng.sample(range(0, 500), rng.randint(1, 40))
    live_ids = []
    saves = []
    for _ in range(rng.randint(1, 60)):
        choice = rng.random()
        if choice < 0.42 and ids:
            pid = ids.pop()
            flow = rng.choice(flows)
            length = rng.randint(1, 12)
            size = rng.randint(0, 20)
            events.append(['enqueue', pid, flow, length, size])
            live_ids.append(pid)
        elif choice < 0.62:
            events.append(['dequeue', rng.randint(1, 4)])
        elif choice < 0.68:
            events.append(['sample'])
        elif choice < 0.74:
            events.append(['repartition', borders(rng, U)])
        elif choice < 0.82 and live_ids:
            events.append(['cancel', rng.choice(live_ids)])
        elif choice < 0.88 and live_ids:
            events.append(['inspect', rng.choice(live_ids)])
        elif choice < 0.90 and policy['kind'] == 'wfq':
            events.append(['weight', rng.choice(flows), rng.randint(1, 16)])
        elif choice < 0.96:
            name = rng.randint(0, 3)
            events.append(['save', name])
            saves.append(name)
        elif saves:
            events.append(['restore', rng.choice(saves)])
        else:
            events.append(['save', rng.randint(0, 3)])
            saves.append(events[-1][1])
    # sometimes cancel/inspect unknown or terminal ids
    for _ in range(rng.randint(0, 3)):
        events.append([rng.choice(['cancel', 'inspect']), rng.randint(600, 700)])
    return {
        'banks': M, 'load_balancers': L,
        'fifo_bytes': rng.choice([1, 4, 12, 30, 100]),
        'pifo_bytes': rng.choice([1, 4, 12, 30, 100]),
        'refill_batch': rng.randint(1, 4),
        'sample_period': rng.choice([1, 2, 3, 5, 100000]),
        'borders': borders(rng, U),
        'policy': policy,
        'events': events,
    }


def main():
    cases = int(sys.argv[1]) if len(sys.argv) > 1 else 200
    seed = int(sys.argv[2]) if len(sys.argv) > 2 else 1
    rng = random.Random(seed)
    bad = 0
    for case in range(cases):
        runs = [make_run(rng) for _ in range(rng.randint(1, 2))]
        request = {'runs': runs}
        expected = {'runs': [Ref(cfg).run(cfg['events']) for cfg in runs]}
        actual = fast(json.loads(json.dumps(request)))
        if actual != expected:
            bad += 1
            print('MISMATCH case', case)
            for k, (a, e) in enumerate(zip(actual['runs'], expected['runs'])):
                if a == e:
                    continue
                print(' run', k)
                for x, y in zip(a['log'], e['log']):
                    if x != y:
                        print('  first log diff\n   got', x, '\n   exp', y)
                        break
                else:
                    if len(a['log']) != len(e['log']):
                        print('  log length', len(a['log']), len(e['log']))
                    for key in e['state']:
                        if a['state'].get(key) != e['state'][key]:
                            print('  state diff', key, '\n   got', a['state'].get(key), '\n   exp', e['state'][key])
            with open('/workspace/tests/fail_%d.json' % case, 'w') as fh:
                json.dump(request, fh, indent=1)
            if bad >= 3:
                break
    print('checked %d cases, %d mismatches' % (case + 1, bad))
    return 1 if bad else 0


if __name__ == '__main__':
    sys.exit(main())
